html = f'''<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>卡牌插画审核表</title>
<style>
*{{margin:0;padding:0;box-sizing:border-box}}
body{{background:#0a0a14;color:#ccc;font-family:system-ui,sans-serif;padding:16px}}
h1{{font-size:18px;color:#fff;margin-bottom:4px}}
.subtitle{{font-size:11px;color:#555;margin-bottom:6px}}
.legend{{font-size:10px;color:#555;margin-bottom:14px;display:flex;gap:16px;flex-wrap:wrap}}
table{{width:100%;border-collapse:collapse;font-size:11px}}
thead th{{background:#111;color:#888;padding:6px 4px;text-align:left;position:sticky;top:0;z-index:10;border-bottom:1px solid #222;font-weight:500}}
tbody td{{padding:6px 4px;border-bottom:1px solid #111;vertical-align:top}}
tbody tr:hover{{background:rgba(255,255,255,0.02)}}
.col-id{{width:36px;color:#666}}
.col-name{{width:72px;font-weight:600;color:#ddd}}
.col-type{{width:42px;font-size:10px}}
.col-domain{{width:30px;font-size:9px;color:#888;text-align:center}}
.col-scene{{min-width:300px;color:#aaa;font-size:12px}}
.col-status{{width:60px;text-align:center}}
.tag{{display:inline-block;padding:1px 6px;border-radius:3px;font-size:9px}}
.tag-atk{{background:#3a1a1a;color:#e55}}
.tag-sup{{background:#1a3a1a;color:#5a5}}
.tag-sum{{background:#3a3a00;color:#fa5}}
.tag-dom{{background:#1a1a3a;color:#5af}}
[contenteditable="true"]{{outline:1px dashed #333;padding:2px 4px;border-radius:2px;min-height:20px;display:block}}
[contenteditable="true"]:focus{{outline:1px solid #5af;background:rgba(85,170,255,0.05)}}
.domain-force{{color:#E74C3C}}.domain-sound{{color:#2ECC71}}.domain-light{{color:#F39C12}}.domain-heat{{color:#E67E22}}.domain-elec{{color:#9B59B6}}
select.status{{background:#111;color:#fff;border:1px solid #333;border-radius:3px;padding:2px 4px;font-size:10px;cursor:pointer}}
select.status:focus{{border-color:#5af}}
.btn-row{{margin-bottom:12px;display:flex;gap:8px}}
.btn{{background:#1a1a30;color:#888;border:1px solid #333;padding:6px 14px;border-radius:4px;cursor:pointer;font-size:11px}}
.btn:hover{{background:#222;color:#aaa}}
.btn.primary{{background:#1a2a1a;border-color:#2a4a2a;color:#5a5}}
.btn.export{{background:#1a1a2a;border-color:#3a3a5a;color:#5af}}
.status-approved{{background:#1a2a1a}}
.status-rejected{{background:#2a1a1a}}
.feedback-cell{{font-size:10px;color:#f5a}}
</style></head><body>
<h1>卡牌插画审核表</h1>
<p class="subtitle">{len(cards_cn)}张卡牌，赛博朋克风格，全部中文。点击「场景理解」或「提示词」单元格直接编辑。</p>
<div class="legend"><span>状态：<b>pending</b>=待审 <b style="color:#5a5">approved</b>=通过 <b style="color:#f55">rejected</b>=驳回</span></div>
<div class="btn-row">
<button class="btn primary" onclick="approveAll()">全部通过</button>
<button class="btn" onclick="filterPending()">只看待审</button>
<button class="btn" onclick="filterRejected()">只看驳回</button>
<button class="btn" onclick="showAll()">显示全部</button>
<button class="btn export" onclick="exportData()">导出 JSON</button>
</div>
<table><thead><tr>
<th class="col-id">ID</th><th class="col-name">名称</th><th class="col-type">类型</th><th class="col-domain">领域</th>
<th>我的场景理解</th><th>AI提示词（可编辑）</th>
<th class="col-status">状态</th><th style="width:100px">修改意见</th>
</tr></thead><tbody id="tb"></tbody></table>
<script>
const cards={cards_json};
const tc={{attack:'tag-atk',support:'tag-sup',summon:'tag-sum',domain:'tag-dom'}};
const tl={{attack:'攻击',support:'辅助',summon:'召唤',domain:'领域'}};
const dm={{'力':'domain-force','声':'domain-sound','光':'domain-light','热':'domain-heat','电':'domain-elec'}};
let states={{}};
function render(){{
  document.getElementById('tb').innerHTML=cards.map(c=>{{
    const st=states[c.id]||'pending';
    let rc='';
    if(st==='approved')rc='status-approved';
    if(st==='rejected')rc='status-rejected';
    return `<tr class="${{rc}}" data-id="${{c.id}}" data-status="${{st}}">
<td class="col-id">${{c.id}}</td>
<td class="col-name">${{c.name}}</td>
<td class="col-type"><span class="tag ${{tc[c.type]||''}}">${{tl[c.type]||c.type}}</span></td>
<td class="col-domain"><span class="${{dm[c.domain]||''}}">${{c.domain}}</span></td>
<td class="col-scene"><div contenteditable="true" data-field="scene" data-id="${{c.id}}">${{c.scene}}</div></td>
<td class="col-scene"><div contenteditable="true" data-field="prompt" data-id="${{c.id}}">${{c.prompt}}</div></td>
<td class="col-status"><select class="status" data-id="${{c.id}}" onchange="upd(this)">
<option value="pending" ${{st==='pending'?'selected':''}}>pending</option>
<option value="approved" ${{st==='approved'?'selected':''}}>approved</option>
<option value="rejected" ${{st==='rejected'?'selected':''}}>rejected</option>
</select></td>
<td><div contenteditable="true" data-field="feedback" data-id="${{c.id}}" class="feedback-cell"></div></td>
</tr>`;}}).join('');
}}
function upd(s){{states[s.dataset.id]=s.value;const r=s.closest('tr');r.dataset.status=s.value;r.className='';if(s.value==='approved')r.classList.add('status-approved');if(s.value==='rejected')r.classList.add('status-rejected');}}
function approveAll(){{cards.forEach(c=>{{states[c.id]='approved'}});render();}}
function filterPending(){{document.querySelectorAll('tbody tr').forEach(r=>{{r.style.display=r.dataset.status==='pending'?'':'none'}});}}
function filterRejected(){{document.querySelectorAll('tbody tr').forEach(r=>{{r.style.display=r.dataset.status==='rejected'?'':'none'}});}}
function showAll(){{document.querySelectorAll('tbody tr').forEach(r=>{{r.style.display=''}});}}
function exportData(){{const d=[];document.querySelectorAll('tbody tr').forEach(r=>{{const id=r.dataset.id;const sc=r.querySelector('[data-field="scene"]')?.textContent||'';const pr=r.querySelector('[data-field="prompt"]')?.textContent||'';const fb=r.querySelector('[data-field="feedback"]')?.textContent||'';d.push({{id,status:states[id]||'pending',scene:sc,prompt:pr,feedback:fb}})}});const b=new Blob([JSON.stringify(d,null,2)],{{type:'application/json'}});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='review_results.json';a.click();}}
render();
</script></body></html>'''

with open('review_illustrations.html','w',encoding='utf-8') as f:
    f.write(html)
print(f'OK: {len(cards_cn)} cards in Chinese')
